<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Bouncing Ball Playground</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #151d35;
      --panel-light: #202b4a;
      --text: #eaf1ff;
      --muted: #91a0c2;
      --accent: #73d7ff;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background:
        radial-gradient(circle at 50% 10%, #1b2b52 0, transparent 42%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      width: min(94vw, 760px);
      text-align: center;
    }

    h1 {
      margin: 0 0 14px;
      font-size: clamp(1.45rem, 3vw, 2.15rem);
      letter-spacing: 0.04em;
      text-shadow: 0 0 22px rgba(115, 215, 255, 0.3);
    }

    .hint {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .stage {
      display: flex;
      justify-content: center;
      padding: 12px;
      border: 1px solid #2c3b63;
      border-radius: 18px;
      background: rgba(13, 20, 40, 0.8);
      box-shadow: 0 18px 55px rgba(0, 0, 0, 0.4), inset 0 0 28px rgba(98, 139, 255, 0.06);
    }

    #sim {
      display: block;
      width: 640px;
      height: 480px;
      max-width: 100%;
      min-width: 400px;
      min-height: 400px;
      border-radius: 10px;
      cursor: crosshair;
      background: #0b1226;
      box-shadow: 0 0 0 1px rgba(125, 170, 255, 0.2), 0 0 30px rgba(57, 136, 255, 0.13);
    }

    .controls {
      display: flex;
      justify-content: center;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 16px;
    }

    button {
      border: 1px solid #3b527f;
      border-radius: 10px;
      padding: 10px 18px;
      color: var(--text);
      background: linear-gradient(180deg, var(--panel-light), var(--panel));
      font: inherit;
      font-weight: 650;
      cursor: pointer;
      transition: transform 120ms ease, border-color 120ms ease, box-shadow 120ms ease;
    }

    button:hover {
      border-color: var(--accent);
      box-shadow: 0 0 16px rgba(115, 215, 255, 0.18);
    }

    button:active {
      transform: translateY(1px) scale(0.98);
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Bouncing Ball Playground</h1>
    <p class="hint">Click anywhere in the arena to add a ball.</p>

    <div class="stage">
      <canvas id="sim" width="640" height="480" aria-label="Bouncing ball simulation"></canvas>
    </div>

    <div class="controls">
      <button id="drop" type="button">Drop Ball</button>
      <button id="play" type="button">Pause</button>
      <button id="clear" type="button">Clear</button>
    </div>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const dropButton = document.getElementById("drop");
      const playButton = document.getElementById("play");
      const clearButton = document.getElementById("clear");

      const w = canvas.width;
      const h = canvas.height;
      const gravity = 0.48;
      const restitution = 0.84;
      const ballsList = [];
      let running = true;
      let animationFrame = 0;
      let lastTime = performance.now();

      function clamp(value, low, high) {
        return Math.max(low, Math.min(high, value));
      }

      function addBall(x, y, vx = 0, vy = 0, r) {
        const radius = r === undefined ? 12 + Math.random() * 7 : Math.max(2, Number(r));
        const safeRadius = Math.min(radius, w / 2, h / 2);
        const ball = {
          x: clamp(Number.isFinite(Number(x)) ? Number(x) : w / 2, safeRadius, w - safeRadius),
          y: clamp(Number.isFinite(Number(y)) ? Number(y) : safeRadius, safeRadius, h - safeRadius),
          vx: Number.isFinite(Number(vx)) ? Number(vx) : 0,
          vy: Number.isFinite(Number(vy)) ? Number(vy) : 0,
          r: safeRadius,
          hue: Math.floor(Math.random() * 360)
        };
        ballsList.push(ball);
        draw();
        return ball;
      }

      function clear() {
        ballsList.length = 0;
        draw();
      }

      function integrate(ball, dt) {
        ball.vy += gravity * dt;
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        if (ball.x - ball.r < 0) {
          ball.x = ball.r;
          if (ball.vx < 0) ball.vx = -ball.vx * restitution;
        } else if (ball.x + ball.r > w) {
          ball.x = w - ball.r;
          if (ball.vx > 0) ball.vx = -ball.vx * restitution;
        }

        if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          if (ball.vy < 0) ball.vy = -ball.vy * restitution;
        } else if (ball.y + ball.r > h) {
          ball.y = h - ball.r;
          if (ball.vy > 0) ball.vy = -ball.vy * restitution;
        }

        // A final clamp guarantees containment even after unusually large time steps.
        ball.x = clamp(ball.x, ball.r, w - ball.r);
        ball.y = clamp(ball.y, ball.r, h - ball.r);
      }

      function step(dt = 1) {
        let amount = Number(dt);
        if (!Number.isFinite(amount) || amount <= 0) amount = 1;

        // Substeps make edge collisions reliable for larger time advances.
        const count = Math.max(1, Math.ceil(amount));
        const slice = amount / count;
        for (let i = 0; i < count; i++) {
          for (const ball of ballsList) integrate(ball, slice);
        }
        draw();
      }

      function balls() {
        return ballsList.map(ball => ({
          x: ball.x,
          y: ball.y,
          vx: ball.vx,
          vy: ball.vy,
          r: ball.r
        }));
      }

      function draw() {
        const gradient = ctx.createLinearGradient(0, 0, 0, h);
        gradient.addColorStop(0, "#101a36");
        gradient.addColorStop(1, "#070d1d");
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, w, h);

        ctx.strokeStyle = "rgba(115, 215, 255, 0.11)";
        ctx.lineWidth = 1;
        for (let x = 40; x < w; x += 40) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, h);
          ctx.stroke();
        }
        for (let y = 40; y < h; y += 40) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(w, y);
          ctx.stroke();
        }

        for (const ball of ballsList) {
          const glow = ctx.createRadialGradient(
            ball.x - ball.r * 0.35, ball.y - ball.r * 0.4, ball.r * 0.08,
            ball.x, ball.y, ball.r * 1.4
          );
          glow.addColorStop(0, "#ffffff");
          glow.addColorStop(0.18, `hsl(${ball.hue}, 95%, 78%)`);
          glow.addColorStop(0.55, `hsl(${ball.hue}, 88%, 58%)`);
          glow.addColorStop(1, `hsla(${ball.hue}, 90%, 40%, 0.2)`);

          ctx.save();
          ctx.shadowColor = `hsla(${ball.hue}, 100%, 65%, 0.8)`;
          ctx.shadowBlur = 18;
          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = glow;
          ctx.fill();
          ctx.restore();
        }
      }

      function animate(now) {
        if (running) {
          const elapsed = Math.min(50, now - lastTime);
          step(elapsed / 16.6667);
        }
        lastTime = now;
        animationFrame = requestAnimationFrame(animate);
      }

      canvas.addEventListener("click", event => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) * (w / rect.width);
        const y = (event.clientY - rect.top) * (h / rect.height);
        addBall(x, y, (Math.random() - 0.5) * 3, -Math.random() * 2);
      });

      dropButton.addEventListener("click", () => {
        addBall(w / 2 + (Math.random() - 0.5) * 100, 35, (Math.random() - 0.5) * 3, 0);
      });

      playButton.addEventListener("click", () => {
        running = !running;
        playButton.textContent = running ? "Pause" : "Play";
        lastTime = performance.now();
      });

      clearButton.addEventListener("click", clear);

      window.sim = { w, h, balls, addBall, clear, step };

      draw();
      animationFrame = requestAnimationFrame(animate);
    })();
  </script>
</body>
</html>
